priority_points(case): need * 2 + tenure, plus 25 when tenure >= 12.
band_name(case): apex at 140 points or more, core at 90 or more, else base.
award_size(case): currently just caps the request at the band cap.
"""

def priority_points(case):
    points = case["need"] * 2 + case["tenure"]
    if case["tenure"] >= 12:
        points = points + 25
    return points

def band_name(case):
    points = priority_points(case)
    if points >= 140:
        return "apex"
    if points >= 90:
        return "core"
    return "base"

def award_size(case):
    band = band_name(case)
    caps = {"apex": 900, "core": 500, "base": 200}
    amount = case["request"]
    cap = caps[band]
    if amount > cap:
        amount = cap
    return amount
